CREATE DATABASE IF NOT EXISTS vmmon CHARACTER SET utf8mb4;
USE vmmon;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, email VARCHAR(120), password_hash VARCHAR(255) NOT NULL, role ENUM('admin','user') DEFAULT 'user', lang CHAR(2) DEFAULT 'en', theme VARCHAR(60) NULL, sound VARCHAR(20) NULL, disabled TINYINT NOT NULL DEFAULT 0, card_order TEXT NULL, card_order_compact TEXT NULL, card_pos TEXT NULL, dash_sort VARCHAR(10) NOT NULL DEFAULT 'layout', dash_view VARCHAR(10) NOT NULL DEFAULT 'normal', last_login DATETIME NULL, last_seen DATETIME NULL, locked_until DATETIME NULL, totp_secret TEXT NULL, totp_enabled TINYINT NOT NULL DEFAULT 0, totp_recovery TEXT NULL, totp_last BIGINT NULL, pending_email VARCHAR(120) NULL, email_token CHAR(64) NULL, email_exp DATETIME NULL, logged_in TINYINT NOT NULL DEFAULT 0, oidc_sub VARCHAR(255) NULL, pw_token CHAR(64) NULL, pw_exp DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(k VARCHAR(50) PRIMARY KEY, v TEXT);
CREATE TABLE servers(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, host VARCHAR(150) NOT NULL, os ENUM('linux','windows') DEFAULT 'linux', os_info VARCHAR(120) NULL, os_full TEXT NULL, info TEXT NULL, is_services TINYINT NOT NULL DEFAULT 0, ignored TINYINT NOT NULL DEFAULT 0, enabled TINYINT NOT NULL DEFAULT 1, comment TEXT NULL, hv_type VARCHAR(10) NULL, hv_conn TEXT NULL, hv_data MEDIUMTEXT NULL, hv_poll DATETIME NULL, hv_status ENUM('up','down') NULL, hv_hidden TEXT NULL, if_show TEXT NULL, nw_hidden TEXT NULL, hv_error VARCHAR(255) NULL, nw_type VARCHAR(12) NULL, nw_role VARCHAR(10) NULL, nw_conn TEXT NULL, nw_data MEDIUMTEXT NULL, nw_poll DATETIME NULL, nw_status ENUM('up','down') NULL, nw_error VARCHAR(255) NULL, pbs_conn TEXT NULL, dash_hidden TINYINT NOT NULL DEFAULT 0, host_sort INT NOT NULL DEFAULT 0, tn_sort INT NOT NULL DEFAULT 0, icon VARCHAR(80) NOT NULL DEFAULT '', maint_until DATETIME NULL, zbx_active TINYINT NOT NULL DEFAULT 0, zbx_host VARCHAR(120) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE server_checks(id INT AUTO_INCREMENT PRIMARY KEY, server_id INT NOT NULL, source ENUM('zabbix','snmp','tcp','url','pbs','docker','ha') NOT NULL, kind VARCHAR(40) NOT NULL, target TEXT NOT NULL, param VARCHAR(1000) NOT NULL DEFAULT '', label VARCHAR(120), interval_sec INT NULL, hidden TINYINT NOT NULL DEFAULT 0, enabled TINYINT NOT NULL DEFAULT 1, mon_up TINYINT NOT NULL DEFAULT 1, mon_ms TINYINT NOT NULL DEFAULT 0, icon VARCHAR(80) NOT NULL DEFAULT '', sort INT NOT NULL DEFAULT 0, last_status ENUM('up','down') NULL, last_detail VARCHAR(255), last_value FLOAT NULL, last_data MEDIUMTEXT NULL, last_check DATETIME NULL, fail_n INT NOT NULL DEFAULT 0, FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
CREATE TABLE check_hist(check_id INT NOT NULL, hr DATETIME NOT NULL, up INT DEFAULT 0, total INT DEFAULT 0, PRIMARY KEY(check_id,hr), FOREIGN KEY(check_id) REFERENCES server_checks(id) ON DELETE CASCADE);
CREATE TABLE check_ms_hist(check_id INT NOT NULL, bk DATETIME NOT NULL, n INT NOT NULL DEFAULT 0, ms_sum DOUBLE NOT NULL DEFAULT 0, ms_max DOUBLE NOT NULL DEFAULT 0, PRIMARY KEY(check_id,bk), FOREIGN KEY(check_id) REFERENCES server_checks(id) ON DELETE CASCADE);
CREATE TABLE disk_hist(server_id INT NOT NULL, dk VARCHAR(190) NOT NULL, bk DATETIME NOT NULL, n INT NOT NULL DEFAULT 0, used_sum DOUBLE NOT NULL DEFAULT 0, used_max DOUBLE NOT NULL DEFAULT 0, PRIMARY KEY(server_id,dk,bk), FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
CREATE TABLE dash_graphs(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, w TINYINT NOT NULL DEFAULT 1, v VARCHAR(8) NOT NULL DEFAULT 'both', cw TINYINT NULL, ch TINYINT NULL, graphs TEXT NOT NULL, lay TINYINT NOT NULL DEFAULT 1, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE load_hist(server_id INT NOT NULL, bk DATETIME NOT NULL, cpu_sum FLOAT DEFAULT 0, cpu_n INT DEFAULT 0, cpu_max FLOAT NULL, mem_sum FLOAT DEFAULT 0, mem_n INT DEFAULT 0, mem_max FLOAT NULL, PRIMARY KEY(server_id,bk), FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
CREATE TABLE alert_rule_groups(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE alert_rules(name VARCHAR(100) NULL, group_id INT NULL, id INT AUTO_INCREMENT PRIMARY KEY, server_id INT NULL, iface VARCHAR(255) NOT NULL DEFAULT '', metric ENUM('cpu','mem','disk','check','offline','net_err','net_drop','net_crc','sys_worker','sys_zbx','sys_recv','swap','hw_temp','hw_fan','net_down','net_util','hv_ping','hv_down','hv_cpu','hv_mem','hv_storage','hv_vm_down','hv_vm_cpu','hv_vm_mem','nw_down','nw_temp','nw_hw','nw_ping','check_ms','src_snmp','src_zabbix','src_pbs','smart','nw_health','zbx','ha_state','ha_supported','ha_updates','ha_unavail','st_ping','st_down','st_temp','st_psu','st_fan','st_hw','st_health','bmc_ping','bmc_down','bmc_temp','bmc_psu','bmc_fan','bmc_hw','bmc_health','nw_psu','nw_fan','smart_temp','log_event','users') NOT NULL, kinds TEXT NULL, s_247 TINYINT NOT NULL DEFAULT 1, s_days VARCHAR(7) NOT NULL DEFAULT '1234567', s_from TIME NOT NULL DEFAULT '00:00:00', s_to TIME NOT NULL DEFAULT '23:59:00', threshold FLOAT DEFAULT 85, minutes INT DEFAULT 5, repeat_min INT DEFAULT 0, emails TEXT NULL, notify_email TINYINT NOT NULL DEFAULT 1, notify_tg TINYINT NOT NULL DEFAULT 0, notify_wh TINYINT NOT NULL DEFAULT 0, notify_sms TINYINT NOT NULL DEFAULT 0, notify_signal TINYINT NOT NULL DEFAULT 0, targets TEXT NULL, enabled TINYINT DEFAULT 1, FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
CREATE TABLE alert_state(rule_id INT NOT NULL, server_id INT NOT NULL, since DATETIME NULL, firing TINYINT DEFAULT 0, last_sent DATETIME NULL, PRIMARY KEY(rule_id,server_id), FOREIGN KEY(rule_id) REFERENCES alert_rules(id) ON DELETE CASCADE, FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
CREATE TABLE alert_log(id BIGINT AUTO_INCREMENT PRIMARY KEY, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, server_id INT NULL, server_name VARCHAR(80), metric VARCHAR(20), event ENUM('alarm','repeat','ok'), message TEXT, mail_result VARCHAR(255), INDEX(ts), INDEX(server_id));
CREATE TABLE net_if(server_id INT NOT NULL, if_index INT NOT NULL, name VARCHAR(100), descr VARCHAR(255), alias VARCHAR(255), type INT DEFAULT 0, speed_mbps INT DEFAULT 0, mac VARCHAR(32), admin TINYINT DEFAULT 0, oper TINYINT DEFAULT 0, in_oct DOUBLE DEFAULT 0, out_oct DOUBLE DEFAULT 0, in_err DOUBLE DEFAULT 0, out_err DOUBLE DEFAULT 0, in_disc DOUBLE DEFAULT 0, out_disc DOUBLE DEFAULT 0, last_ts INT NULL, rate_in DOUBLE NULL, rate_out DOUBLE NULL, err_pm DOUBLE NULL, disc_pm DOUBLE NULL, ips VARCHAR(255) NULL, in_crc DOUBLE NULL, crc_pm DOUBLE NULL, PRIMARY KEY(server_id,if_index), FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
CREATE TABLE net_hist(server_id INT NOT NULL, if_index INT NOT NULL, bk DATETIME NOT NULL, n INT DEFAULT 0, in_sum DOUBLE DEFAULT 0, in_max DOUBLE DEFAULT 0, out_sum DOUBLE DEFAULT 0, out_max DOUBLE DEFAULT 0, err_sum DOUBLE DEFAULT 0, err_max DOUBLE DEFAULT 0, disc_sum DOUBLE DEFAULT 0, disc_max DOUBLE DEFAULT 0, PRIMARY KEY(server_id,if_index,bk), FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
CREATE TABLE check_events(id BIGINT AUTO_INCREMENT PRIMARY KEY, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, check_id INT NULL, server_id INT NULL, server_name VARCHAR(80), svc TINYINT NOT NULL DEFAULT 0, label VARCHAR(120), target VARCHAR(255), status ENUM('up','down') NOT NULL, detail VARCHAR(255), dur INT NULL, INDEX(check_id,id), INDEX(ts));
CREATE TABLE app_log(id BIGINT AUTO_INCREMENT PRIMARY KEY, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, level ENUM('debug','info','warning','error') NOT NULL, src VARCHAR(20) NOT NULL, usr VARCHAR(50) NULL, msg VARCHAR(600) NOT NULL, INDEX(ts), INDEX(level,id), INDEX(src,id));

CREATE TABLE login_fail(id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, ip VARCHAR(45), ts DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,ts));
CREATE TABLE IF NOT EXISTS user_passkeys(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, cred_id VARCHAR(400) NOT NULL, pubkey TEXT NOT NULL, sign_count BIGINT NOT NULL DEFAULT 0, name VARCHAR(80) NOT NULL DEFAULT 'Passkey', created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, last_used DATETIME NULL, UNIQUE KEY(cred_id), INDEX(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS trusted_devices(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token_hash CHAR(64) NOT NULL, expires DATETIME NOT NULL, created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS icons(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, svg MEDIUMTEXT NOT NULL, created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_prefs(user_id INT NOT NULL, k VARCHAR(60) NOT NULL, v MEDIUMTEXT NULL, PRIMARY KEY(user_id,k));
CREATE TABLE dash_heads(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, w TINYINT NOT NULL DEFAULT 2, color VARCHAR(12) NOT NULL DEFAULT 'acc', text VARCHAR(120) NOT NULL DEFAULT 'Headline', tcol VARCHAR(12) NOT NULL DEFAULT 'auto', lay TINYINT NOT NULL DEFAULT 1, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE alert_events(id BIGINT AUTO_INCREMENT PRIMARY KEY, server_id INT NULL, server_name VARCHAR(80), kind VARCHAR(20) NOT NULL, sev ENUM('warning','critical') NOT NULL, detail VARCHAR(500), started DATETIME NOT NULL, ended DATETIME NULL, dur INT NULL, notified TINYINT NOT NULL DEFAULT 0, reason VARCHAR(255), INDEX(started), INDEX(ended), INDEX(server_id,kind));
CREATE TABLE device_groups(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, sort INT NOT NULL DEFAULT 0, icon VARCHAR(80) NOT NULL DEFAULT '');
CREATE TABLE device_group_members(group_id INT NOT NULL, server_id INT NOT NULL, PRIMARY KEY(group_id,server_id), INDEX(server_id), FOREIGN KEY(group_id) REFERENCES device_groups(id) ON DELETE CASCADE, FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
INSERT INTO device_groups(name,sort) VALUES('Production servers',1),('Lab servers',2),('Networking',3),('Services',4);
INSERT IGNORE INTO device_group_members(group_id,server_id) SELECT (SELECT id FROM device_groups WHERE name='Networking' ORDER BY id LIMIT 1),id FROM servers WHERE nw_type IS NOT NULL AND COALESCE(nw_role,'') NOT IN ('nas','san','bmc');
INSERT IGNORE INTO device_group_members(group_id,server_id) SELECT (SELECT id FROM device_groups WHERE name='Services' ORDER BY id LIMIT 1),id FROM servers WHERE is_services=1;
CREATE TABLE IF NOT EXISTS api_tokens(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, prefix VARCHAR(12) NOT NULL, token_hash CHAR(64) NOT NULL, enabled TINYINT NOT NULL DEFAULT 1, created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_used DATETIME NULL, last_ip VARCHAR(45) NULL, UNIQUE KEY(token_hash));
CREATE TABLE IF NOT EXISTS zbx_active(server_id INT NOT NULL, kh CHAR(32) NOT NULL, k VARCHAR(500) NOT NULL, val MEDIUMTEXT NULL, ts INT NULL, req INT NOT NULL DEFAULT 0, PRIMARY KEY(server_id,kh), FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS log_events(id BIGINT AUTO_INCREMENT, ts DATETIME NOT NULL, server_id INT NULL, src_ip VARCHAR(45) NOT NULL, kind ENUM('trap','syslog') NOT NULL, sev TINYINT NOT NULL DEFAULT 6, facility TINYINT NULL, host VARCHAR(120) NULL, prog VARCHAR(80) NULL, oid VARCHAR(190) NULL, msg TEXT NOT NULL, fw_act VARCHAR(10) NULL, fw_dir VARCHAR(4) NULL, fw_proto VARCHAR(12) NULL, fw_src VARCHAR(45) NULL, fw_dst VARCHAR(45) NULL, fw_sport INT NULL, fw_dport INT NULL, fw_in VARCHAR(40) NULL, fw_out VARCHAR(40) NULL, fw_rule VARCHAR(40) NULL, PRIMARY KEY(id,ts), INDEX(server_id,ts), INDEX(fw_src), INDEX(fw_dst)) ENGINE=InnoDB PARTITION BY RANGE COLUMNS(ts) (PARTITION p0 VALUES LESS THAN ('2000-01-01 00:00:00'), PARTITION pmax VALUES LESS THAN (MAXVALUE));
-- Dygnssammanställning av brandväggstrafik (v2.56)
CREATE TABLE IF NOT EXISTS log_fw_daily(day DATE NOT NULL, server_id INT NOT NULL DEFAULT 0, act VARCHAR(10) NOT NULL, dir VARCHAR(4) NOT NULL DEFAULT '', proto VARCHAR(12) NOT NULL DEFAULT '', src VARCHAR(45) NOT NULL DEFAULT '', dst VARCHAR(45) NOT NULL DEFAULT '', dport INT NOT NULL DEFAULT 0, rule VARCHAR(40) NOT NULL DEFAULT '', cnt BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(day,server_id,act,dir,proto,src,dst,dport,rule), INDEX(server_id,day)) ENGINE=InnoDB;

-- MIB-filer (v2.73)
CREATE TABLE IF NOT EXISTS mib_files(id INT AUTO_INCREMENT PRIMARY KEY, module VARCHAR(100) NOT NULL, fname VARCHAR(200) NOT NULL, n INT NOT NULL DEFAULT 0, defs MEDIUMTEXT NOT NULL, uploaded DATETIME NOT NULL, KEY(module)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mib_names(oid VARCHAR(255) NOT NULL PRIMARY KEY, name VARCHAR(120) NOT NULL, module VARCHAR(100) NOT NULL, kind CHAR(1) NOT NULL DEFAULT 'o', enums TEXT NULL, KEY(name)) ENGINE=InnoDB;
